parts.script:
if (ctx.state.done) {
  ctx.log(`Already created and placed node ${ctx.state.nodeId} + edge ${ctx.state.edgeId} earlier — guarded by ctx.state.done so this only runs once.`);
  return { value: ctx.state.count, state: ctx.state, leftBadge: { text: String(ctx.state.count), color: '#2f8f4e' } };
}

// 1. Create the underlying Part and Connector — same as the createPart demo, no view
//    placement yet for either one.
const cap = ctx.createPart({ type: 'BusinessCapability', label: 'Generated & Placed Capability', model: ctx.part.model });
const conn = ctx.createConnector({ from: ctx.part.id, to: cap.id, connectorType: 'c', relationship: 'Association' });

// 2. Place the new part as a visible node on THIS view — createPart never does this.
const node = ctx.createNode({ objectId: cap.id, x: 380, y: 60 });
ctx.log(`Placed "${cap.label}" on view "${ctx.currentView}" at (${node.x}, ${node.y}).`);

// 3. Place the connector as a visible edge — needs BOTH endpoints already placed on this
//    view (this node already is, from the saved file; the new one just was, in step 2).
//    createConnector never draws a line by itself, same reasoning as createNode/createPart.
const edge = ctx.createNodeConnector({ objectId: conn.id });
ctx.log(`Placed the edge between them (viewMember ${edge.id}).`);

// 4. Calling createNode/createNodeConnector AGAIN for the same part/connector is a no-op
//    (find-or-create) — proves neither creates a duplicate even if a script calls them
//    every tick by mistake.
const nodeAgain = ctx.createNode({ objectId: cap.id, x: 900, y: 900 });
const edgeAgain = ctx.createNodeConnector({ objectId: conn.id });
ctx.log(`Repeat calls returned the SAME node/edge (id match: ${nodeAgain.id === node.id} / ${edgeAgain.id === edge.id}) — no duplicates, and the node did NOT move to (900, 900).`);

return {
  value: 1,
  state: { done: true, count: 1, capId: cap.id, nodeId: node.id, edgeId: edge.id },
  leftBadge: { text: '1', color: '#2f8f4e' },
};
